import{_ as d,o as e,c as o,a2 as r}from"./chunks/framework.RycU2wFZ.js";const _=JSON.parse('{"title":"Agent 身份与行为审计规范 (T1.8 Specification)","description":"","frontmatter":{},"headers":[],"relativePath":"zh/specs/agent-audit.md","filePath":"zh/specs/agent-audit.md","lastUpdated":null}'),a={name:"zh/specs/agent-audit.md"};function n(c,t,i,s,l,g){return e(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="agent-身份与行为审计规范-t1-8-specification" tabindex="-1">Agent 身份与行为审计规范 (T1.8 Specification) <a class="header-anchor" href="#agent-身份与行为审计规范-t1-8-specification" aria-label="Permalink to &quot;Agent 身份与行为审计规范 (T1.8 Specification)&quot;">​</a></h1><blockquote><p><strong>版本</strong>：v1.0.0 (T1.8 规范：Agent 身份与行为审计)<br><strong>状态</strong>：<strong>已定稿 (Approved Specification)</strong><br><strong>适用范围</strong>：AgentPay Go Gateway 数据面、控制面、审计流与控制台<br><strong>前置规范</strong>：<a href="./multitenant-data-model">specs/multitenant-data-model.md</a>, <a href="./audit-events">specs/audit-events-spec.md</a></p></blockquote><hr><h2 id="_1-目标与边界" tabindex="-1">1. 目标与边界 <a class="header-anchor" href="#_1-目标与边界" aria-label="Permalink to &quot;1. 目标与边界&quot;">​</a></h2><p>三类需求，对应三种不同的能力，不可混为一谈：</p><table tabindex="0"><thead><tr><th>需求</th><th>本质</th><th>时效要求</th></tr></thead><tbody><tr><td>可见性与排查：租户查看自己的 Agent 做了什么</td><td>查询与时间线</td><td>准实时，允许短暂延迟</td></tr><tr><td>风险控制：发现并拦截失控的 Agent</td><td><strong>执行（enforcement）</strong>，不是事后审计</td><td><strong>同步，在请求路径内</strong></td></tr><tr><td>合规留痕：事后可追溯、可导出</td><td>完整性、保留、导出</td><td>持久、可验证</td></tr></tbody></table><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p><strong>边界声明（写入公开文档）</strong><br> 网关只能审计 Agent 的<strong>可观测行为</strong>（调用、支付、策略决策），无法得知 Agent 的内部推理过程，也不能证明其主观意图。</p></div><hr><h2 id="_2-核心设计原则" tabindex="-1">2. 核心设计原则 <a class="header-anchor" href="#_2-核心设计原则" aria-label="Permalink to &quot;2. 核心设计原则&quot;">​</a></h2><ol><li><strong>一条事件流，三个消费者</strong>：所有行为都统一写成标准审计事件；可见性读取、风险检测、合规导出都消费同一份事件，不各自另记。</li><li><strong>执行不依赖审计管道</strong>：预算、频率、白名单、停用等拦截在请求路径内<strong>同步判断</strong>，使用本地及实时计数，绝不能等异步日志分析出结果再拦截。</li><li><strong>观测与声明严格分开</strong>： <ul><li>网关自己看到的（<code>observed</code>）是客观事实（例如 API Key 绑定的 <code>agent_id</code>、实际耗时、上游状态码、扣费金额）；</li><li>Agent 通过请求头自报的（<code>declared</code>，如 <code>session_id</code>、<code>task_id</code>、<code>tool_name</code>）不可信，只用于关联和展示，<strong>严禁用于授权或计费判定</strong>。</li></ul></li><li><strong>默认只存元数据</strong>：请求体、响应体不入审计；内容样本只能显式开启、脱敏、单独设保留期、限制访问。</li><li><strong>只追加（Append-Only）</strong>：审计事件不可修改、不可删除；更正通过追加审计事件完成。</li></ol><hr><h2 id="_3-agent-实体模型" tabindex="-1">3. Agent 实体模型 <a class="header-anchor" href="#_3-agent-实体模型" aria-label="Permalink to &quot;3. Agent 实体模型&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>类型</th><th>说明与安全约束</th></tr></thead><tbody><tr><td><code>agent_id</code></td><td>string (PK)</td><td>格式：<code>agt_...</code>，主键</td></tr><tr><td><code>tenant_id</code></td><td>string (FK)</td><td>租户归属，强隔离边界</td></tr><tr><td><code>project_id</code></td><td>string (FK)</td><td>项目归属</td></tr><tr><td><code>name</code></td><td>string</td><td>展示名</td></tr><tr><td><code>status</code></td><td>string</td><td>枚举：<code>active</code> / <code>suspended</code> / <code>revoked</code></td></tr><tr><td>绑定关系</td><td>关联表</td><td>一个 Agent 可有多个 API Key；一个 API Key 必须唯一属于一个 Agent</td></tr><tr><td>策略引用</td><td>JSONB / 关联</td><td>预算、频率、路由白名单、风险规则（可继承项目默认）</td></tr></tbody></table><h3 id="核心运行时约束" tabindex="-1">核心运行时约束 <a class="header-anchor" href="#核心运行时约束" aria-label="Permalink to &quot;核心运行时约束&quot;">​</a></h3><ul><li><strong>身份单一事实来源</strong>：所有入站请求必须能解析到 <code>agent_id</code>，且必须由凭据（API Key / 签名）确定，<strong>绝对不能由客户端请求头自报决定</strong>。</li><li><strong>一键停用（Kill Switch）</strong>：当 Agent 状态为 <code>suspended</code> 或 Key 被 <code>revoked</code> 时，网关必须在数秒内（通过即时失效通道或 RCU 刷新）拒绝后续新请求；进行中的请求按已有状态机规则完成或释放冻结。</li></ul><hr><h2 id="_4-审计事件结构规范" tabindex="-1">4. 审计事件结构规范 <a class="header-anchor" href="#_4-审计事件结构规范" aria-label="Permalink to &quot;4. 审计事件结构规范&quot;">​</a></h2><h3 id="_4-1-通用字段来源规范" tabindex="-1">4.1 通用字段来源规范 <a class="header-anchor" href="#_4-1-通用字段来源规范" aria-label="Permalink to &quot;4.1 通用字段来源规范&quot;">​</a></h3><table tabindex="0"><thead><tr><th>字段</th><th>来源</th><th>类型与说明</th></tr></thead><tbody><tr><td><code>event_id</code></td><td>观测 (<code>observed</code>)</td><td>全局唯一 UUID/CUID，作为写入幂等键</td></tr><tr><td><code>event_type</code></td><td>观测 (<code>observed</code>)</td><td>事件枚举（见 4.2）</td></tr><tr><td><code>occurred_at</code></td><td>观测 (<code>observed</code>)</td><td>网关高精度时间戳（UTC）</td></tr><tr><td><code>tenant_id</code>, <code>project_id</code>, <code>agent_id</code></td><td>观测 (<code>observed</code>)</td><td>由 API Key 解析所得，防伪造</td></tr><tr><td><code>request_id</code></td><td>观测 (<code>observed</code>)</td><td>网关入站统一链路 ID</td></tr><tr><td><code>route_id</code>, <code>config_version</code></td><td>观测 (<code>observed</code>)</td><td>命中的路由与生效配置指纹</td></tr><tr><td><code>actor</code></td><td>观测 (<code>observed</code>)</td><td><code>agent</code> / <code>admin</code> / <code>system</code></td></tr><tr><td><code>session_id</code>, <code>task_id</code>, <code>parent_request_id</code>, <code>tool_name</code></td><td><strong>声明 (<code>declared</code>)</strong></td><td>Agent 自报字段；长度严格受限（最大 128 字符），字符集过滤防注入；<strong>完全可选</strong></td></tr><tr><td>关联 ID</td><td>观测 (<code>observed</code>)</td><td><code>payment_intent_id</code>, <code>settlement_id</code>, <code>fulfillment_id</code>, <code>hold_id</code></td></tr><tr><td><code>prev_hash</code>, <code>hash</code></td><td>观测 (<code>observed</code>)</td><td>可选哈希链防篡改指纹（接口预留）</td></tr></tbody></table><h3 id="_4-1-1-声明字段-declared-缺省处理与安全不变量" tabindex="-1">4.1.1 声明字段（Declared）缺省处理与安全不变量 <a class="header-anchor" href="#_4-1-1-声明字段-declared-缺省处理与安全不变量" aria-label="Permalink to &quot;4.1.1 声明字段（Declared）缺省处理与安全不变量&quot;">​</a></h3><p>声明字段由客户端通过 <code>X-Session-ID</code>、<code>X-Task-ID</code>、<code>X-Tool-Name</code> 等请求头自报，属于<strong>完全可选</strong>字段。</p><table tabindex="0"><thead><tr><th>处理维度</th><th>客户端传入自报 Header</th><th>客户端未传自报 Header (缺省)</th></tr></thead><tbody><tr><td><strong>网关数据面</strong></td><td>白名单过滤并截断至 128 字符后存入事件</td><td>字段提取为 <code>&quot;&quot;</code>，<strong>正常放行并处理业务，不报错</strong></td></tr><tr><td><strong>计费与扣款</strong></td><td><strong>严禁参与</strong>任何授权或计费判定逻辑</td><td><strong>完全不受影响</strong>，按 API Key 关联的钱包原子划转</td></tr><tr><td><strong>风控与熔断</strong></td><td>同步执行单笔上限、24h 预算、Kill Switch</td><td><strong>完全不受影响</strong>，网关内部计数严格执行</td></tr><tr><td><strong>控制台展示</strong></td><td>可按 <code>session_id</code> 进行多调用折叠聚合与会话审计</td><td>归入“全部会话”，按独立原子请求时序展现</td></tr><tr><td><strong>时间线徽标</strong></td><td>展示绿色 <code>[网关观测]</code> + 黄色 <code>[自报声明]</code> 徽标</td><td>仅展示绿色 <code>[网关观测]</code> 徽标，信息不失真</td></tr></tbody></table><h3 id="_4-2-事件类型-canonical-event-types" tabindex="-1">4.2 事件类型 (Canonical Event Types) <a class="header-anchor" href="#_4-2-事件类型-canonical-event-types" aria-label="Permalink to &quot;4.2 事件类型 (Canonical Event Types)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>类型 (Type)</th><th>领域</th><th>含义与包含内容</th></tr></thead><tbody><tr><td><code>agent.request</code></td><td>请求</td><td>请求到达与结果（HTTP 状态码、耗时毫秒、上游大小、请求指纹哈希）</td></tr><tr><td><code>agent.policy_decision</code></td><td>策略</td><td>策略判定：<code>allow</code> / <code>deny</code>，命中的规则 ID、拒绝原因码、版本</td></tr><tr><td><code>agent.spend</code></td><td>支付</td><td>资金操作：冻结、确认扣款、解冻释放、链上结算（金额、币种、支付方式）</td></tr><tr><td><code>agent.anomaly</code></td><td>风控</td><td>风险规则命中：规则 ID、安全阈值、观测指标值</td></tr><tr><td><code>agent.control</code></td><td>控制</td><td>管理动作：停用、恢复、Key 撤销/轮换、预算调整（操作人与原因）</td></tr><tr><td><code>agent.export</code></td><td>合规</td><td>审计数据导出操作（导出人、筛选条件、导出记录行数）</td></tr></tbody></table><hr><h2 id="_5-风险控制-执行层" tabindex="-1">5. 风险控制（执行层） <a class="header-anchor" href="#_5-风险控制-执行层" aria-label="Permalink to &quot;5. 风险控制（执行层）&quot;">​</a></h2><h3 id="_5-1-v1-同步策略执行" tabindex="-1">5.1 v1 同步策略执行 <a class="header-anchor" href="#_5-1-v1-同步策略执行" aria-label="Permalink to &quot;5.1 v1 同步策略执行&quot;">​</a></h3><ul><li><strong>Agent 级独立预算</strong>：按 Agent 设置 24 小时滚动窗口与月度总额度，直接与虚拟钱包 Hold 联动。</li><li><strong>Agent 级限频（Rate Limiting）</strong>：针对单 Agent 细粒度控制 QPS/RPM，防止 Agent 逻辑死循环或高频刷量。</li><li><strong>路由白名单（Route Allowlist）</strong>：严格限制 Agent 仅能访问授权的目标上游 API。</li><li><strong>单笔上限（Max Per Tx）</strong>：限制单次交互的最大代币消耗额度。</li><li><strong>秒级一键停用（Kill Switch）</strong>：管理员停用 Agent 或撤销 Key 后，网关即时失效缓存，毫秒级阻断入站请求。</li></ul><h3 id="_5-2-v1-x-规则检测与告警" tabindex="-1">5.2 v1.x 规则检测与告警 <a class="header-anchor" href="#_5-2-v1-x-规则检测与告警" aria-label="Permalink to &quot;5.2 v1.x 规则检测与告警&quot;">​</a></h3><ul><li><strong>行为异常规则</strong>：调用量激增、花费速率骤增、高频连续被拒绝、首次访问冷门路由、非工作时段异常活跃。</li><li><strong>默认只告警不自动阻断</strong>：避免因误判导致业务工作流中断；自动阻断须管理员显式开启并设置冷却期。</li><li><strong>通知渠道</strong>：Web 控制台通知、Webhook 回调推送。</li></ul><hr><h2 id="_6-可见性-读取层" tabindex="-1">6. 可见性（读取层） <a class="header-anchor" href="#_6-可见性-读取层" aria-label="Permalink to &quot;6. 可见性（读取层）&quot;">​</a></h2><ol><li><strong>Agent 总览与列表</strong>：状态、近期调用量、花费总额、策略拒绝率。</li><li><strong>行为时间线（Timeline）</strong>：按时间顺序展示事件流；支持按 <code>session_id</code> / <code>task_id</code>（自报声明）聚合工作流会话。</li><li><strong>多维筛选</strong>：时间范围、目标路由、HTTP 状态码、策略决策结果、支付方式、事件类型。</li><li><strong>穿透详情</strong>：单次请求一键穿透关联的 <code>payment_intent</code>、<code>settlement</code>、<code>hold</code>、<code>fulfillment</code> 以及命中的具体策略版本。</li><li><strong>多租户权限边界</strong>：跨租户 100% 不可见；管理员跨租户操作必须记录独立的高危审计事件。</li></ol><hr><h2 id="_7-合规留痕与导出" tabindex="-1">7. 合规留痕与导出 <a class="header-anchor" href="#_7-合规留痕与导出" aria-label="Permalink to &quot;7. 合规留痕与导出&quot;">​</a></h2><ol><li><strong>只追加完整性</strong>：审计表仅允许 <code>INSERT</code>，数据库层面剥离 <code>UPDATE</code> 与 <code>DELETE</code> 权限。</li><li><strong>事务性发件箱（Transactional Outbox）</strong>：涉及资金划转（Hold/Capture/Release）的事件，必须在数据库强事务中与账本流水原子写入，确保“扣款必有审计”。</li><li><strong>分层保留期</strong>： <ul><li>元数据事件：长期保留（默认 1 年以上）；</li><li>内容样本（若租户显式开启）：短期保留（默认 7-30 天），受独立脱敏策略与权限管控。</li></ul></li><li><strong>安全导出</strong>：仅租户管理员权限可导出（CSV / JSONL 格式）；导出前自动脱敏敏感字段；每次导出本身强行记入 <code>agent.export</code> 事件。</li></ol><hr><h2 id="_8-威胁与风险缓解" tabindex="-1">8. 威胁与风险缓解 <a class="header-anchor" href="#_8-威胁与风险缓解" aria-label="Permalink to &quot;8. 威胁与风险缓解&quot;">​</a></h2><table tabindex="0"><thead><tr><th>威胁场景</th><th>风险级别</th><th>网关缓解机制</th></tr></thead><tbody><tr><td>请求头自报伪造 <code>agent_id</code></td><td><strong>严重 (Critical)</strong></td><td>网关强制剥离客户端请求头传入的 <code>X-Agent-ID</code>，仅以 API Key 解析作为唯一事实</td></tr><tr><td>声明字段日志注入攻击</td><td><strong>高 (High)</strong></td><td>声明字段限制白名单字符与最大 128 字符长度，违规内容截断或无害化转义</td></tr><tr><td>凭据泄漏冒充 Agent</td><td><strong>高 (High)</strong></td><td>配合 IP 白名单、单笔上限、秒级一键停用阻断</td></tr><tr><td>停用生效延迟窗口期</td><td><strong>高 (High)</strong></td><td>停用/撤销走内存 RCU 即时通知，避免长时间依赖本地缓存过期</td></tr><tr><td>跨租户越权查询审计</td><td><strong>严重 (Critical)</strong></td><td>数据访问层强制注入 <code>tenant_id</code> 参数与行级安全策略（RLS）</td></tr></tbody></table>',39)])])}const b=d(a,[["render",n]]);export{_ as __pageData,b as default};
